#!/bin/bash
greet() {
    local name="$1"
    echo "Hello, $name!"
}

# Call the function
greet "Alice"
greet "Bob"

# Function with return
is_even() {
    local num=$1
    return $((num % 2))
}

if is_even 4; then
    echo "Even"
fi

Argument Parsing with getopts:
#!/bin/bash
usage() {
    echo "Usage: $0 [-n name] [-a age] [-v]"
    exit 1
}

verbose=false
while getopts "n:a:v" opt; do
    case $opt in
        n) name="$OPTARG" ;;
        a) age="$OPTARG" ;;
        v) verbose=true ;;
        *) usage ;;
    esac
done

echo "Name: ${name:-unknown}"
echo "Age: ${age:-unknown}"
$verbose && echo "Verbose mode on"

awk Text Processing:
# Field extraction
awk '{print $1, $3}' data.txt
awk -F: '{print $1, $6}' /etc/passwd  # custom separator

# Pattern matching
awk '/error/ {print NR, $0}' log.txt
awk '$3 > 100 {print $1, $3}' data.txt

# BEGIN/END blocks
awk 'BEGIN {sum=0} {sum+=$3} END {print "Total:", sum}' sales.txt

# Formatted output
awk '{printf "%-10s %5d\n", $1, $2}' file.txt

# Multi-condition
awk '{
    if ($1 ~ /^[A-Z]/) {
        print "Starts with uppercase:", $0
    } else {
        print "Other:", $0
    }
}' file.txt

# Process substitution
awk '!seen[$0]++' file.txt  # remove duplicate lines without sort

Error Handling (set -e, trap):
#!/usr/bin/env bash
set -euo pipefail

# Error handler
error_handler() {
    local line=$1
    local command=$2
    echo "Error on line $line: $command" >&2
}
trap 'error_handler $LINENO "$BASH_COMMAND"' ERR

# EXIT trap (cleanup)
cleanup() {
    rm -f /tmp/temp_*
    echo "Cleaned up"
}
trap cleanup EXIT

# Graceful signal handling
handle_sigint() {
    echo "Interrupted, cleaning up..."
    exit 1
}
trap handle_sigint SIGINT SIGTERM

# Fallback pattern
mkdir -p /some/dir || {
    echo "Failed to create directory" >&2
    exit 1
}

